const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||''}</svg>`;
const esc=(value)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=(name)=>String(name||'D').split(' ').filter(Boolean).slice(0,2).map(s=>s[0].toUpperCase()).join('');
const validDateKey=(value)=>/^\d{4}-(0[1-9]|1[0-2])-([0-2]\d|3[01])$/.test(String(value||''))&&(()=>{const d=new Date(`${value}T00:00:00Z`);return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value})();
const dateParts=(date)=>{const value=String(date||'').slice(0,10),safe=validDateKey(value)?value:today();return new Date(`${safe}T00:00:00+08:00`)};
const monthName=(month)=>{const value=String(month||'');const key=/^\d{4}-(0[1-9]|1[0-2])$/.test(value)?value:`${today().slice(0,7)}`;return new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric',timeZone:'Asia/Manila'}).format(dateParts(key+'-01'))};
const niceDate=(date,options={weekday:'long',month:'long',day:'numeric'})=>new Intl.DateTimeFormat('en-US',{...options,timeZone:'Asia/Manila'}).format(dateParts(date));
const today=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`};
const manilaNowInput=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`};
const timeLabel=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
const spanLabel=(a,b)=>`${timeLabel(a)} – ${timeLabel(b)}`;
const hours=(start,end)=>end?`${((new Date(end)-new Date(start))/3600000).toFixed(2)} h`:'In progress';
const money=(cents)=>cents>0?new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(cents/100):'Rate pending';
const peso=(cents)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(cents/100);
const hourlyLabel=(cents)=>cents>0?`${money(cents)}/hour`:'Rate pending';
const shiftMinutes=b=>Math.max(0,(Date.parse(`${b.end_date||b.date}T${b.end_time}:00Z`)-Date.parse(`${b.date}T${b.start_time}:00Z`))/60000);
const quotedPay=(start,end,cents,startDate,endDate)=>cents>0?money(Math.round((startDate&&endDate?Math.max(0,(Date.parse(`${endDate}T${end}:00Z`)-Date.parse(`${startDate}T${start}:00Z`))/60000):(Number(end.slice(0,2))*60+Number(end.slice(3)))-(Number(start.slice(0,2))*60+Number(start.slice(3))))*cents/60)):'Amount pending';
const bookingPay=b=>quotedPay(b.start_time,b.end_time,b.rate_cents,b.date,b.end_date||b.date);
const bookingWindow=b=>`${niceDate(b.date,{month:'short',day:'numeric',year:'numeric'})}${(b.end_date||b.date)!==b.date?` – ${niceDate(b.end_date,{month:'short',day:'numeric',year:'numeric'})}`:''} · ${spanLabel(b.start_time,b.end_time)}`;
const actualPay=(record,cents)=>record?.clock_out_at&&cents>0?money(Math.round((new Date(record.clock_out_at)-new Date(record.clock_in_at))*cents/3600000)):'Not recorded';
const viewPaths={dashboard:'/',mycalendar:'/my-calendar',calendar:'/team-calendar',find:'/find-shifts',requests:'/requests',attendance:'/time-evidence',team:'/team-scorecard',users:'/user-management',telegram:'/telegram-alerts',settings:'/settings',guide:'/help'};
const pathViews=Object.fromEntries(Object.entries(viewPaths).map(([view,path])=>[path,view]));
pathViews['/doctor-management']='team';
pathViews['/calendar']='calendar';
function scorecardRange(preset){
 const now=today(),year=Number(now.slice(0,4)),month=Number(now.slice(5,7));
 const date=(value)=>value.toISOString().slice(0,10);
 if(preset==='this_month')return {from:`${now.slice(0,7)}-01`,to:now};
 if(preset==='last_month')return {from:date(new Date(Date.UTC(year,month-2,1))),to:date(new Date(Date.UTC(year,month-1,0)))};
 return {from:date(new Date(Date.UTC(year,month-4,1))),to:date(new Date(Date.UTC(year,month-1,0)))};
}
