 const myShifts=admin?[]:state.allBookings.filter(b=>b.status==='approved'&&b.date<=month+'-31'&&(b.end_date||b.date)>=month+'-01').sort((a,b)=>a.date.localeCompare(b.date)||a.start_time.localeCompare(b.start_time));
 const scheduleRows=myShifts.map(b=>{const record=state.attendance.find(a=>a.booking_id===b.id),timeHint=record?(record.clock_out_at?'Time in/out recorded':'Clock-in active; finish in Time & evidence'):b.date>today()?'Time entry opens on the shift date':'';return `<tr class="clickable-row" data-details-row="${b.id}" tabindex="0" aria-label="Open shift details for ${bookingWindow(b)}"><td><strong>${bookingWindow(b).split(' · ')[0]}</strong><div class="subtle">Booking #${b.id}</div></td><td>${spanLabel(b.start_time,b.end_time)}</td><td>${esc(b.location||'Not specified')}</td><td>${hourlyLabel(b.rate_cents)}</td><td><strong>${bookingPay(b)}</strong><div class="subtle">Scheduled estimate${record?.clock_out_at?` · ${actualPay(record,b.rate_cents)} based on actual time`:''}</div></td><td><div class="actions-cell">${b.date<=today()&&!record?`<button class="button soft tiny" data-manual="${b.id}">Add time in/out & evidence</button>`:''}</div>${timeHint?`<div class="subtle calendar-time-note">${timeHint}</div>`:''}</td></tr>`}).join('');
 const myScheduleSection=admin?'':`<section class="card list-card schedule-list"><div class="card-header"><div><h2>My booked shifts</h2><p>Approved shifts for ${monthName(month)}, with location, pay, and time entry status.</p></div></div><div class="table-wrap"><table><thead><tr><th>Day</th><th>Time</th><th>Location</th><th>Hourly rate</th><th>Shift amount</th><th>Time in/out</th></tr></thead><tbody>${scheduleRows||'<tr><td colspan="6" class="table-empty">No booked shifts this month. Open Find reliever posts to request a time.</td></tr>'}</tbody></table></div></section>`;
 const calendarPanel=`<section class="card calendar-panel"><div class="card-header"><div><h2>${admin?'Team schedules':'My calendar'}</h2><p>Choose a date to review its shifts</p></div><div class="month-controls"><button class="button secondary icon-button" data-month="-1" aria-label="Previous month">‹</button><strong>${monthName(month)}</strong><button class="button secondary tiny" data-action="today">Today</button><button class="button secondary icon-button" data-month="1" aria-label="Next month">›</button></div></div><div class="filter-line">${admin?`<div><label for="doctor-filter">Team member</label><br><select id="doctor-filter">${doctors.map(d=>`<option value="${d.id}" ${d.id===Number(state.doctorId)?'selected':''}>${esc(d.name)} · ${esc(d.role)}</option>`).join('')}</select></div>`:'<div class="calendar-scope">Your shifts and requests</div>'}<div class="calendar-counts"><span><i class="dot" aria-hidden="true"></i>${bookedCount} booked</span><span><i class="dot amber" aria-hidden="true"></i>${pendingCount} pending</span></div></div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${days.map(dayCell).join('')}</div><div class="mobile-days">${['M','T','W','T','F','S','S'].map(d=>`<span class="mobile-weekday" aria-hidden="true">${d}</span>`).join('')}${days.map(d=>{if(!d)return '<span class="mobile-day-blank" aria-hidden="true"></span>';const dayBookings=relevant.filter(b=>b.date===d);return `<button class="mobile-day ${d===state.selected?'selected':''} ${d===today()?'today':''}" data-day="${d}" aria-controls="selected-day-details" aria-pressed="${d===state.selected}" aria-label="${niceDate(d)}; ${dayBookings.filter(b=>b.status==='approved').length} booked, ${dayBookings.filter(b=>b.status==='pending').length} pending"><span class="date-tile"><strong>${Number(d.slice(-2))}</strong></span><span class="mobile-day-dots" aria-hidden="true">${dayBookings.some(b=>b.status==='approved')?'<i class="dot"></i>':''}${dayBookings.some(b=>b.status==='pending')?'<i class="dot amber"></i>':''}</span></button>`}).join('')}</div><div class="calendar-footer">Philippine Time · Select a date to view details</div></section>`;
 const dayPanel=`<aside class="card day-panel" id="selected-day-details" aria-label="Selected day details"><div class="card-header"><div><div class="selected-day-label">Selected day</div><h2>${niceDate(state.selected,{weekday:'short',month:'short',day:'numeric'})}</h2><p>${niceDate(state.selected,{year:'numeric'})} · Philippine Time</p></div></div><div class="day-panel-body"><section class="day-section"><div class="day-section-heading"><h3>Bookings & requests</h3><span>${selectedBookings.length}</span></div>${bookingCards||'<p class="day-empty">No bookings or requests for this day.</p>'}</section></div></aside>`;
 shell(`${pageHeading('Schedule',admin?'Team Calendar':'My schedule',admin?'Review team schedules and booked shifts.':'Your booked shifts, requests, and time records.',actions)}<div class="content-grid calendar-workspace">${calendarPanel}${dayPanel}</div>${myScheduleSection}`,admin?'Team Calendar':'My schedule');
