 openModal('Request this shift',`${niceDate(post.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · ${spanLabel(post.start_time,post.end_time)}`,`<div class="callout" style="margin-bottom:16px">${esc(post.location)} · ${hourlyLabel(post.rate_cents)}. Complete the required responses and attach the requested files. Sending your request closes this post to other doctors while an admin reviews it.</div><h3 class="section-title">Required skills</h3>${questionsMarkup||'<p class="inline-note">No skill questions were added to this post.</p>'}${requiredUploads.length?`<h3 class="section-title">Required files</h3>${uploadsMarkup}`:''}${area('note','Note for admin (optional)','Anything the admin should know')}`,'reliever-request-form','Request shift');
