  if(id==='availability-form')return runForm(form,async f=>{const requiredQuestions=[...form.querySelectorAll('.skill-question')].map(row=>({question:row.querySelector('.skill-prompt').value.trim(),type:row.querySelector('.skill-response-type').value})),requiredUploads=[...form.querySelectorAll('input[name="requiredUploads"]:checked')].map(input=>input.value);await api('/api/reliever-posts','POST',{...Object.fromEntries(f),requiredQuestions,requiredUploads});modal.close();await refresh();toast('Reliever post published for doctors.');});
 if(id==='reliever-request-form')return runForm(form,async f=>{const count=Number(form.dataset.questionCount||0),answers=Array.from({length:count},(_,index)=>({answer:String(f.get(`skillAnswer${index}`)||'').trim()})),uploads={};if(form.elements.relieverPhoto?.files?.[0])uploads.photo=await filePayload(form.elements.relieverPhoto.files[0],6);if(form.elements.relieverDocument?.files?.[0])uploads.document=await filePayload(form.elements.relieverDocument.files[0],8);const result=await api(`/api/reliever-posts/${form.dataset.id}/request`,'POST',{note:f.get('note'),answers,uploads});modal.close();await refresh();toast(result.notification==='failed'?'Request saved. Telegram alert failed; ask your admin to check Settings.':result.notification==='not_configured'?'Request saved. Telegram is not configured yet.':'Request sent. This post is no longer available to other doctors.');});
 if(id==='my-day-form'){modal.close();return}
 if(id==='edit-my-shift-form')return runForm(form,async f=>{const values=Object.fromEntries(f);await api(`/api/my-shifts/${form.dataset.id}`,'PATCH',{...values,date:values.startDate,start:values.startTime,end:values.endTime});modal.close();await refresh();toast('Your shift was updated.');});
 if(id==='scorecard-range-form')return runForm(form,async f=>{const from=String(f.get('from')),to=String(f.get('to'));if(from>to)throw new Error('From date must be on or before To date.');const score=await api(`/api/team-scorecard?from=${from}&to=${to}`);state.scorecardFrom=from;state.scorecardTo=to;state.teamScorecard=score;render();});
 if(id==='assign-form')return runForm(form,async f=>{const values=Object.fromEntries(f),created=await api('/api/admin-bookings','POST',{...values,date:values.startDate,start:values.startTime,end:values.endTime});modal.close();await refresh();toast(created.created>1?`${created.created} shift offers sent. The team member can accept or decline them.`:'Shift offer sent. The team member can accept or decline it.');});
 if(id==='rate-form')return runForm(form,async f=>{await api(`/api/availability/${form.dataset.id}`,'PATCH',{hourlyRate:f.get('hourlyRate')});modal.close();await refresh();toast('Hourly rate updated for new bookings.');});
 if(id==='booking-rate-form')return runForm(form,async f=>{await api(`/api/bookings/${form.dataset.id}/rate`,'PATCH',{hourlyRate:f.get('hourlyRate')});modal.close();await refresh();toast('Booking rate updated.');});
 if(id==='request-form')return runForm(form,async f=>{const result=await api('/api/bookings','POST',Object.fromEntries(f));modal.close();await refresh();toast(result.notification==='failed'?'Request saved. Telegram alert failed; ask your admin to check Settings.':result.notification==='not_configured'?'Request saved. Telegram is not configured yet.':'Request sent to the admin.');});
 if(id==='user-form')return runForm(form,async f=>{await api('/api/users','POST',Object.fromEntries(f));modal.close();await refresh();toast('User account created.');});
 if(id==='reset-form')return runForm(form,async f=>{await api(`/api/users/${form.dataset.id}`,'PATCH',{password:f.get('password')});modal.close();toast('Password reset. Share it privately.');});
 if(id==='telegram-form')return runForm(form,async f=>{state.telegram=await api('/api/telegram','PUT',Object.fromEntries(f));render();toast('Telegram settings saved.');});
