  if(target.dataset.action==='toggle-menu'){const sidebar=target.closest('.sidebar');const open=sidebar.classList.toggle('menu-open');target.setAttribute('aria-expanded',String(open));return}
  if(target.dataset.addSkillQuestion!==undefined){const list=modal.querySelector('.skill-question-list');if(list.querySelectorAll('.skill-question').length>=8)return toast('A post can have up to 8 skill questions.',true);list.insertAdjacentHTML('beforeend',skillQuestionRow());modal.querySelectorAll('[data-remove-skill]').forEach(button=>button.disabled=false);list.lastElementChild?.querySelector('.skill-prompt')?.focus();return}
  if(target.dataset.removeSkill!==undefined){const list=target.closest('.skill-question-list'),rows=list?.querySelectorAll('.skill-question');if(rows?.length<=1)return toast('Keep at least one required skill question.');target.closest('.skill-question')?.remove();return}
  if(target.dataset.myLayout){state.myCalendarLayout=target.dataset.myLayout;render();return}
  if(target.dataset.myView){state.myCalendarMode=target.dataset.myView;render();return}
  if(target.dataset.myDay){state.myCalendarDay=target.dataset.myDay;state.month=target.dataset.myDay.slice(0,7);render();openMyDayModal(target.dataset.myDay);return}
