  if(target.dataset.action==='logout'){refreshSequence++;await api('/api/logout','POST');state.user=null;state.view='dashboard';history.replaceState(null,'','/');authScreen(false);return}
  if(target.dataset.action==='today'){state.month=today().slice(0,7);state.selected=today();await refresh();return}
  if(target.dataset.action==='refresh'){invalidateReads();await refresh();toast('Calendar updated.');return}
  if(target.dataset.month){const [y,m]=state.month.split('-').map(Number);const d=new Date(Date.UTC(y,m-1+Number(target.dataset.month),1));state.month=d.toISOString().slice(0,7);state.selected=state.month+'-01';await refresh();return}
  if(target.dataset.day){state.selected=target.dataset.day;render();[...document.querySelectorAll('[data-day]')].find(button=>button.dataset.day===state.selected&&button.offsetParent!==null)?.focus({preventScroll:true});if(innerWidth<=680)document.querySelector('.day-panel')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return}
  if(target.dataset.modal){modalFor(target.dataset.modal);return}
